import{_ as r,a as t,b as o,c as l}from"./chunks/43294501002a7634d957.DMG8g16S.js";import{_ as n,C as s,o as i,c as h,j as e,a as c,E as d,a5 as m}from"./chunks/framework.DNkHA0lr.js";const w=JSON.parse('{"title":"如何拯救你搞砸的人生(基于证据)","description":"","frontmatter":{"title":"如何拯救你搞砸的人生(基于证据)","originalTitle":"How To Unf*ck Your Life (Evidence Based)","date":"2025-04-19","originalUrl":"https://thedankoe.com/letters/how-to-unfck-your-life-evidence-based/","minutes":19,"sourceHash":"076c19792ac85be42b9e300b0304939c25844e8035d40c9826ce5d0206d68036","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-unfck-your-life-evidence-based/"}]]},"headers":[],"relativePath":"letters/how-to-unfck-your-life-evidence-based.md","filePath":"letters/how-to-unfck-your-life-evidence-based.md"}'),u={name:"letters/how-to-unfck-your-life-evidence-based.md"};function g(f,p,b,_,k,q){const a=s("ArticleMeta");return i(),h("div",null,[p[0]||(p[0]=e("h1",{id:"如何拯救你搞砸的人生-基于证据",tabindex:"-1"},[c("如何拯救你搞砸的人生(基于证据) "),e("a",{class:"header-anchor",href:"#如何拯救你搞砸的人生-基于证据","aria-label":'Permalink to "如何拯救你搞砸的人生(基于证据)"'},"​")],-1)),d(a),p[1]||(p[1]=m('<p><a href="https://www.youtube.com/embed/Ug_VkmCPeM8?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>你的生活感觉很糟糕,是因为你的脑子里充满了把它解读为糟糕的信念。</p><p>但心理学指向的真相是:</p><p><em>你正处在改变人生的最佳位置。</em></p><p>然而,大多数人并不知道这一点,于是他们在自己的境况中困住了好几年。有时甚至是几十年。他们从未意识到,自己距离一种完全不同的人生体验,只差一次转变。</p><p>现在,你可能觉得自己被困在一份你讨厌的职业里。</p><p>或者你可能在跟负面情绪不断搏斗。</p><p>又或者……你可能只是感觉自己一直在原地打转,努力想让某件事情成功,却因为总是从零开始而不断丧失动力。</p><p>幸运的是,在20世纪中叶,心理学领域出现了一个鲜为人知的突破,它表明人类的价值观、动机和思维方式会随着时间的推移,在个体和社会层面上,以<em>可预测的阶段</em>不断演化。</p><p>这意味着,当你理解了自己所处的阶段,以及取得进展所需的确切“条件”时,现在看起来不可能的事情就会变得必然。</p><p>你的大脑会从字面意义上重构它处理现实的方式。</p><p>这不同于任何现代自助式的“止痛贴”——那些东西只能提供暂时的动力,并且总会失效,因为它们没有从根本层面改变<em>你是谁</em>。</p><p>相反,这一理论揭示了你的大脑需要“经历”的确切顺序,才能创造持久的改变。</p><p>过去4年里,我花了大量时间,把晦涩的书籍、长篇讲座和我自己的经历综合起来,希望能整理出一份有用的指南,帮助你摆脱困境。</p><h2 id="改变人类潜能的理论" tabindex="-1">改变人类潜能的理论 <a class="header-anchor" href="#改变人类潜能的理论" aria-label="Permalink to &quot;改变人类潜能的理论&quot;">​</a></h2><p>我们提到的心理学突破被称为“存在层级”理论(Levels Of Existence)。</p><p>它由克莱尔·W·格雷夫斯博士(Dr. Clare W. Graves)提出,并进一步影响了其他理论,例如:</p><ul><li><strong>螺旋动力学</strong>(由唐·贝克 Don Beck 和克里斯托弗·科文 Christopher Cowan 推广)</li><li><strong>自我发展的9个阶段</strong>(<a href="/letters/how-to-join-the-top-1-of-intelligence-full-guide">我们之前讨论过这个</a>)</li><li><strong>AQAL模型</strong>(肯·威尔伯 Ken Wilber 在上述理论基础上做出的扩展,将它们全部综合在一起)</li></ul><p><img src="'+r+'" alt=""></p><p>就本文而言,我们将聚焦于螺旋动力学模型。</p><p>简而言之,该理论指出,人类的价值系统或世界观(这些影响着我们如何解读世界、做出决策……换句话说,是我们理解现实的操作系统)会沿着一条向上的螺旋,经历各个阶段不断演化。</p><p>这些阶段就是我们思维方式的<em>结构</em>。</p><p>我们每个人作为个体,都会随着年龄增长和自我发展沿着这条螺旋向上移动。</p><p>但这不仅适用于个人,你会发现它同样适用于整个社会。如果你能理解这一点,就能看懂当今许多政治斗争、职场文化(比如每周80小时的工作制),以及宗教机构为何在全球心智份额中日渐失去阵地的原因。</p><p>现在,存在两个层级,即旧范式和新范式,它们各自容纳着若干阶段。</p><p>当然,我写这篇文章的目标,是给你提供工具,帮你识别自己当前所处的位置,并超越到新的阶段,让你能从新的视角看待自己的人生,并开启实现更高层次成功所需的心智空间。</p><h3 id="第一层级阶段-第一层级思考者" tabindex="-1">第一层级阶段(第一层级思考者) <a class="header-anchor" href="#第一层级阶段-第一层级思考者" aria-label="Permalink to &quot;第一层级阶段(第一层级思考者)&quot;">​</a></h3><p>第一层级代表着“旧范式”的思维方式。</p><p>这些阶段在很大程度上受生存驱动,并由匮乏需求驱使。每个阶段都相信自己的世界观是“正确”或“唯一”的思考方式,就像红派对蓝派的政治,或者商业大师们把自己的电商模式当作唯一真理来传授(我自己也犯过这个毛病!)</p><p>最后,这些阶段往往是<em>对生活作出反应</em>。他们按照自己的编程生活,以可预测的、常常显得像照本宣科的方式回应各种情况。就像和一个笃信基督教的人交谈,感觉像是在跟《圣经》对话;或者和一个立场僵化的民主党人交谈,感觉像是在跟电视新闻频道对话。</p><p>当然,这些阶段本身都不算坏。</p><p>每个人都会在人生的某个领域经历这些阶段。</p><p>但是,如果你被困在一个不够理想的阶段里,事情就会变得非常糟糕,而这在第一层级中很容易发生。</p><p>以下是这些阶段,以及我希望有帮助的示例:</p><p><strong>阶段1)米色——生存意识</strong></p><p>米色思考者专注于满足基本的生存需求。</p><p>在今天的世界里,这个阶段越来越罕见(占人口不到0.1%),人们通常在童年早期就离开了这个阶段。</p><p><strong>阶段2)紫色——群体中的安全感</strong></p><p>紫色阶段大约占人口的10%,主要属于部落社会和氏族群体。</p><p>我猜大多数读者并不生活在这种条件下,所以我们不会在这里深入探讨。</p><p><strong>阶段3)红色——力量与行动</strong></p><p>尽管这个阶段主要存在于发展中国家和帮派地盘中,但其中的教训很重要。它曾是过去伟大帝国的关键阶段,但我们作为社会已基本从中演化出来。</p><p>这些阶段的关键在于,尽管它们可能是你的“基线”世界观或思维方式,但你永远不会真正“离开”任何一个阶段。你是超越并包含它们的特性。</p><p>你从来都不是真正只处于<em>一个</em>阶段。</p><p>如果你正处在人生中一段特别有压力的时期,你很容易调用这个阶段,以便掌控某种形式的力量或权威。</p><p>如果你观察体育迷在电视机前生气、当自己支持的球队开始落后时(或某个政党即将输给另一方时)大喊大叫,你可以直接观察到人们如何瞬间改变思维方式,开始“攻击”对方,以试图重新夺回权力。</p><p><strong>阶段4)蓝色——秩序与目的</strong></p><p>如今世界上大多数人(约40%)都处于蓝色阶段。</p><p>蓝色思考者重视结构、规则、明确的目的和稳定性,这些通常是由某个外部来源赋予他们的,比如某种宗教或效率系统的价值准则。</p><p>一个典型的例子就是那些把所有决策都外包给严格教条(比如基督教或伊斯兰教)的“圣经吼手”。</p><p>在工作和职业领域,蓝色重视等级分明、稳定的工作。他们遵守公司政策以规避风险。他们想要确定性。</p><p><strong>阶段5)橙色——成就与成功</strong></p><p>虽然大多数人处于蓝色阶段,但我认为大多数看这篇文章的人处于橙色阶段,同时不少人正跳入绿色阶段,有时甚至跳入第二层级。</p><p>橙色思考者重视个人成就、理性和个人成功。</p><p>他们是设定目标的人,是自助爱好者,是那些不惜一切代价追求胜利的人。</p><p>在宗教或灵性方面,这是大多数人开始为了个人成长而质疑传统的阶段。许多人变成了无神论者,也有许多人只是不知道该信什么,也不想去弄清楚(直到更高阶段才会去探究)。</p><p>在工作和职业方面,人们往往分成两个阵营:追求自己的副业或创业项目,或者攀爬公司阶梯。两者都能提供足够的挑战。</p><p><strong>阶段6)绿色——社群与和谐</strong></p><p>绿色在我心中占有特殊的位置,因为我还记得自己在大学时期经历的“嬉皮士阶段”,那正好发生在我对自己成长过程中被灌输的宗教产生叛逆之后不久。</p><p>“一切本来就很好,伙计。”</p><p>我感觉那是我第一次窥见绿色阶段,而当时我在整个大学期间基本上还处于橙色阶段,在我生活的某些领域现在依然如此。</p><p>绿色重视连接、共识和意义。他们通常是进步派、后现代主义者,专注于普世之爱,常见于学术圈——这既有好的一面,也有不好的一面。</p><p>主要的问题是,绿色阶段很容易陷入肯·威尔伯所说的“无视角疯狂”(aperspectival madness)。</p><p>本质上,“无视角疯狂”发生在个人或社会承认多元视角的有效性(这是好事),却随后陷入一种相对主义陷阱,无法或不愿将这些视角整合起来,或在它们之间做出价值判断(这就成了问题)。</p><p>后现代主义者——好吧,不是真正的后现代主义者,而是那些将自己伪装成后现代主义者、实际上仍残留着大量蓝色和红色特质的人(意味着他们仍然相信有一个“正确的视角”,那就是“没有视角”)——想要拆解等级制度和享有特权的视角(比如身份/性别政治),而在这样做的过程中,他们创造出了自己以支配为核心的等级制度(把等级制度判定为“坏”本身仍是一种价值判断,把等级制度放在了他们无意识等级制度的最底层),这种做法丝毫不顾及演化和现实的结构。</p><h3 id="第二层级阶段-第二层级思考者" tabindex="-1">第二层级阶段(第二层级思考者) <a class="header-anchor" href="#第二层级阶段-第二层级思考者" aria-label="Permalink to &quot;第二层级阶段(第二层级思考者)&quot;">​</a></h3><p>第一层级与第二层级之间的关键转变在于:第一层级各阶段相信自己已经达到了正确的世界观,并常常在不自知的情况下,试图把这种世界观强加给别人。</p><p>而第二层级各阶段则认识到,每个阶段都是人类发展中必要且有价值的一部分,每个阶段都有其针对自身生活条件的恰当回应方式。</p><p><img src="'+t+'" alt=""></p><p>格雷夫斯和贝克——这两位发展心理学理论的创立者——认为从第一层级到第二层级的转变,是意识层面的一次巨大飞跃。这是从生存层面的价值观跃升到“存在层面”的价值观,其重要程度可与人类意识本身的诞生相媲美。</p><p><strong>阶段7)黄色——整合式的灵活性</strong></p><p>黄色思考者重视系统性思维,以及根据情境调整解决方案。</p><p>他们明白,一件事情的内容高度依赖于其所处的语境,就像“跳”(jump)这个词在两个不同的句子中会呈现出完全不同的意味:</p><p><em>这个男人在蹦床上跳跃。</em></p><p><em>这个男人妄下结论(jumped to conclusions)。</em></p><p>仔细想想这一点,并把它应用到你脑海中的每一个情境、词语、行动、想法等等上。如果你能进入这种思维阶段,人生就会获得显著的深度。</p><p>这个阶段能够整合来自不同视角的多种方法。在效率方面,他们能在结构(蓝色)、创新(橙色)和目的(绿色)之间取得平衡,打造出一条比单独使用其中任何一种都更有效的定制路径。他们不属于“你不需要固定routine”这一队,也不属于“你需要固定routine”那一队,他们属于“去做你自己那套破事儿”这一队。</p><p>在灵性和政治方面,他们具有整合性。他们超越群体界限,从每个视角中提取真理,就像现在有些人开始融合东方与西方思想,以形成一种更具影响力、更全面的意义构建方式。</p><p><strong>阶段8)绿松石色——整体性的心流</strong></p><p>绿松石色思考者重视全球意识、整体性视角和相互连接的系统。</p><p>他们建立具有三重底线——人、地球、利润——的企业,承担起与他们对世界产生的相互关联影响相关的更高责任。我们已经多次谈到这一点,我在《<a href="https://thedankoe.com/purpose" target="_blank" rel="noreferrer">使命与利润</a>》第3章中也部分讨论过这个话题。</p><p>在灵性层面,这正是意识层面的探索、天人合一,以及盖亚理论(Gaia theory)开始扎根的地方。</p><p>所有这些阶段都遵循着一个总体趋势:</p><p>随着每个阶段的递进，我们关注的圈子会从以自我为中心扩展到以宇宙为中心。也就是说，一开始我们只关心自己，然后是家庭或部落，然后是整个世界，以此类推——随着我们的心智发展出更多的意义、复杂性和责任感。</p><p>最后，这些阶段以螺旋方式向上移动，因此得名。</p><p>从米色阶段开始，每个阶段都在自我表达和自我牺牲（以自我为中心和以他人为中心）之间摆动。</p><p>在米色阶段，人专注于纯粹的生存和自我照顾。在接下来的紫色阶段，人在社群中寻求安全感。在红色阶段，人寻求个人权力，而蓝色阶段则在有组织的宗教之类的事物中寻求秩序与目标。以此类推。</p><p>好了，跟我坚持一下，因为在你能准确地把这个模型应用到你的生活之前，我们需要理解几个重要的概念。</p><p>但一旦你理解了它们，你就再也无法忽视它们了，你看待世界的方式将永远改变。</p><p>这将为你搭建生活的舞台，让你能够导航到越来越高的存在层次。</p><h3 id="迷因-memes-的重要性-不-不是那种表情包" tabindex="-1">迷因（Memes）的重要性（不，不是那种表情包） <a class="header-anchor" href="#迷因-memes-的重要性-不-不是那种表情包" aria-label="Permalink to &quot;迷因（Memes）的重要性（不，不是那种表情包）&quot;">​</a></h3><blockquote><p>还有其他的信息模式在相互竞争，以维持自身的形态并跨越时间传播自己。例如，语言之间存在竞争，宗教、科学理论、生活方式、技术，甚至我们所谓“自我”那一意识领域的构成要素之间也是如此。</p><p>——米哈里·契克森米哈伊（Mihaly Csikszentmihalyi）</p></blockquote><p>迷因（Memes）。</p><p>不，不是你在手机上无限滑动看到的那种表情包（尽管那些也是迷因）。</p><p>迷因就像基因，但作用于意识或心智层面。</p><p>迷因是从一个人传播到另一个人的文化信息单位。一个（有人爱、有人恨的）典型例子就是埃隆·马斯克（Elon Musk）誓言要摧毁的“觉醒心智病毒”（Woke Mind Virus）。对我来说，这正是肯·威尔伯（Ken Wilber）为处于绿色阶段的人所创造的那种“无视角疯狂”（aperspectival madness）。</p><p>迷因之所以引人入胜，是因为它揭示了一个其他任何生物都不具备的独特特征：</p><p>虽然动物和人类都试图在物理层面上生存和繁衍（他们试图传播其<em>基因</em>中的信息），但人类还试图在概念层面上生存和繁衍（他们试图传播其<em>心智——用迷因</em>中的信息）。</p><p>基因已经不足以提高我们的生存几率了，所以通过某种我并不完全了解的过程，我们进化到了心智的层面。</p><p>我们发明了语言。我们发明了宗教。我们发明了工具和技术，比如飞机、衣服和火，使我们几乎能在任何环境中生存——不像动物只能在自己的细分领域中生存繁荣（试着把北极熊和狮子互换一下位置，看看它们会变成什么样）。</p><p>你现在所生活的这个世界背后隐藏的过程，要归功于一件小小的事情：</p><p>自我。</p><p>那种我们思考自身意识与他人关系时所产生的奇异循环。</p><p>从生存的角度来说，当有人挑战人类的信念时，人类会<em>感受到</em>威胁。当我们身份认同的一部分受到攻击时，我们会感到需要“防御”自己，比如我们的政治立场、宗教信仰，或者我们认为是生活一部分的任何其他事物——比如你的伴侣决定去健身房，这暴露了你因为不跟随而产生的不安，因为你害怕改变带来的痛苦——你的旧自我可能会因此“死去”。</p><p>在螺旋动力学（Spiral Dynamics）中，前面阐述的这些阶段被称为价值观迷因（vMEMEs，Value System Memes）。</p><p>从整体上看，迷因代表了为什么某些观念能引起我们的共鸣，而另一些则不能。</p><p>你的价值观——信念、标准、参照点，或身份认同的其他要素——塑造了什么对你重要、什么值得被注意。</p><p>如果你重视健康，并且为此设立了一个标准，一旦违反（比如一周没去健身房）就会让你感到受威胁，那么你就会注意到能帮你解决这个问题的机会。</p><p>如果你不重视健康，或者不重视财务稳定，你就会继续注意到那些让你停留在原处的事物。机会会从你眼前溜走，因为多巴胺不会为了让你朝着最佳健康或财务方向持续生存而被激发。</p><p>螺旋动力学的各个阶段正因此而重要。</p><p>你所处的阶段，很大程度上决定了你在现实中能注意到什么，以及你能获得哪些机会。</p><p>而你所达到的阶段越高，你就越能调动下面各阶段的能力，这意味着你既有能力也有智慧去发现各种成功的机会，并在螺旋上升的过程中优雅地实现它们。</p><p>那么问题来了，我该如何超越让我感到被困住的那个阶段，向上移动？</p><p>好消息是：</p><p>你正处在改变的最佳位置。</p><h2 id="如何搞好你被搞砸的人生" tabindex="-1">如何搞好你被搞砸的人生 <a class="header-anchor" href="#如何搞好你被搞砸的人生" aria-label="Permalink to &quot;如何搞好你被搞砸的人生&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>首先，我们需要理解<em>变化的顺序</em>。</p><p>当你从一个阶段过渡到另一个阶段时，可以预期会经历以下4个“阶段”：</p><ul><li><strong>Alpha（阿尔法）</strong> —— 生活美好而正常。有秩序。</li><li><strong>Beta（贝塔）</strong> —— 当你进入一个新阶段时，疑虑开始出现。继续做同样的事只会让情况更糟。</li><li><strong>Gamma（伽马）</strong> —— 你感到迷失。一切混乱而动荡。这正是你可能被困住、感觉无路可走的地方。</li><li><strong>Delta（德尔塔）</strong> —— 事情开始生机勃发。你迅速取得进展，达到一个新的基准线。这是你学到最多、<em>感受到</em>成长的阶段。</li></ul><p>你可能之前也经历过这个顺序，只是没意识到。</p><p>我个人经历过很多次。</p><p>在我的事业中，事情会先稳定一段时间。然后我会感觉到有些东西需要改变，或者我注意到我的那些系统不再像往常那样为我服务了（我会从收入、参与度、客户满意度等方面注意到这一点）。</p><p>然后，事情开始变得混乱。我被卡在“我原来做的事”和“我还没完全理解的正在尝试的事”之间。</p><p>最终，事情开始奏效。秩序开始回归。我创下了收入的新高，同时也知道随后会有一次微小的回落，回到基准线。</p><p>有趣的是，我在了解螺旋动力学之前就注意到了这个顺序。</p><p>我在<a href="/letters/how-to-focus-for-12-hours-a-day-on-your-purpose">之前的一封信</a>中讨论过“进步的周期”，其中提到了这些阶段：</p><ul><li><strong>困惑期</strong> —— 在一段稳定期之后，你感到迷失。</li><li><strong>好奇期</strong> —— 你开始好奇如何达到下一个层次。</li><li><strong>强度期</strong> —— 你不断尝试，直到找到那一个关键点，然后进步开始激增。</li><li><strong>稳定期</strong> —— 你达到一个新的基准线，直到这个循环不可避免地再次重复。</li></ul><p>这些都很好，但你要如何真正地为自己蓄力，达到一个新的发展阶段呢？</p><p>我们把重点放在肯·威尔伯（Ken Wilber）“唤醒、清理、成长”（Wake up, Clean up, Grow up）人类发展框架中的“成长”部分。</p><p><strong>唤醒（Wake up）</strong>指的是意识到超越自我（ego）之外的真实本性——进入超越日常清醒意识的意识状态。</p><p><strong>清理（Clean up）</strong>指的是通过阴影工作进行心理疗愈——处理那些正在造成不必要伤害的无意识或被压抑的自我部分。</p><p><strong>成长（Grow up）</strong>指的是认知、道德和视角层面的发展——扩展你的认知复杂性和世界观，同时培养从多重视角看待问题的能力。</p><p>关于唤醒和清理的部分，我们留到以后的信里再谈，但就成长而言，以下是达到新发展阶段所需的条件：</p><h3 id="_0-以ai作为教练来引导变化" tabindex="-1">0）以AI作为教练来引导变化 <a class="header-anchor" href="#_0-以ai作为教练来引导变化" aria-label="Permalink to &quot;0）以AI作为教练来引导变化&quot;">​</a></h3><p>AI令人惊叹之处在于，它能够为你量身定制专属的方法。</p><p>我无法给你极其具体可执行的步骤来达到下一个阶段，因为那需要一整本书来逐一介绍每个阶段可能的策略……而且我还得设法破解你的大脑，获取你的经历和世界观的访问权限，而这大概是不可能发生的。</p><p>以下是我希望你去做的事：</p><p><strong>1 –</strong> <a href="https://kortex.co/" target="_blank" rel="noreferrer"><strong>登录 Kortex</strong></a> <strong>并完成“生活重启地图”（The Life Reset Map）工作流</strong></p><p>你可以在 Chat &gt; Plan 中找到它</p><p><img src="'+l+'" alt=""></p><p>完成访谈式问题后，它会生成一份全面的蓝图，包括你的人生愿景、目标、自我教育计划以及可能需要掌握的技能。</p><p>你可以通过AI消息底部的“创建新文档”按钮，将此输出保存为一份文档。（这在下一步会很有用。）</p><p><strong>2 —— 用螺旋动力学训练AI，并请它帮助引导你迈向下一个阶段。</strong></p><p><a href="https://app.kortex.co/public/document/468c8d82-f6eb-4724-993d-df7f77cbdae6" target="_blank" rel="noreferrer">这里有一份文档，你可以复制我关于螺旋动力学的笔记</a>，里面附有如何配合AI使用它的说明，还包含提示词。</p><p>你需要把之前的“生活重启地图”作为上下文，连同螺旋动力学的笔记一起接入，然后请AI帮你识别你目前处于哪个阶段。</p><p><em>在你和AI聊完之后，请它把整段对话总结出来，然后把它保存为一份文档。</em></p><p><a href="https://www.loom.com/share/3750275702b34f168252fdf835999c01?sid=9b696f91-3964-4b0f-b3f5-92cfee225190" target="_blank" rel="noreferrer">我制作了一段简短的 Loom 视频，向你演示如何操作。</a></p><p><strong>3 —— 在你感到卡住时，使用“成为我的清晰教练”（Be My Clarity Coach）工作流来帮助你</strong></p><p>到这一步，你现在已经拥有以下文档：</p><ul><li>你的“生活重启地图”</li><li>螺旋动力学笔记</li><li>基于你所处阶段的具体建议</li></ul><p>现在，你可以前往 Chat &gt; Plan &gt; Be My Clarity Coach，将这些文档作为上下文附加进去，然后问它你应该开始做什么。</p><p>如果你完成它给出的挑战并持续提问，你会取得很大的进步。</p><p>在你前进的过程中，请记住以下这些条件：</p><h3 id="_1-拥有改变的潜能" tabindex="-1">1）拥有改变的潜能 <a class="header-anchor" href="#_1-拥有改变的潜能" aria-label="Permalink to &quot;1）拥有改变的潜能&quot;">​</a></h3><p>如果你想达到下一个阶段，改变必须是可能的。</p><p>你需要具备技能积累、资源，或者能让你看到改变潜力的环境。</p><p>这对应着苏珊娜·库克-格鲁特（Susanne Cook-Greuter）自我发展理论中“横向发展”（horizontal development）的概念。</p><p>为了垂直向上（进入新阶段），一个人必须在其当前阶段内积累足够的知识、技能和经验。你无法在没有充分发展现有阶段的情况下跳跃到新阶段。</p><p>这需要你在目前生活中正在做的事情上，去教育自己、去练习、去追求目标，并<em>不断改进</em>。</p><h3 id="_2-解决尚未解决的问题" tabindex="-1">2）解决尚未解决的问题 <a class="header-anchor" href="#_2-解决尚未解决的问题" aria-label="Permalink to &quot;2）解决尚未解决的问题&quot;">​</a></h3><p>每个阶段都会呈现一组独特的问题。</p><p>我个人喜欢把自我发展看作是一系列无穷无尽的问题——一旦被解决，其意义和复杂性就会增加，随着你不断解决它们，生活也会变得越来越有趣。</p><p>由于你们大多数人都处于蓝色到绿色之间的阶段，而且我们关注的是个人生活，这些问题几乎总是会涉及三大领域：</p><ul><li>工作</li><li>健康</li><li>关系</li></ul><p>这三者相互交织，彼此之间的影响极大。</p><p>如果你的健康正在影响你的心理和情绪状态，你就无法在工作或关系中发挥出最佳水平。而如果你的工作或关系压力过大，你的健康也会受到冲击。</p><p>在工作方面，这可能意味着换一份职业，或者重新调整心态，让工作变得更有乐趣。</p><p>在关系方面，这可能意味着要进行一些艰难的对话。</p><p>在健康方面，这可能只是像每天散步15分钟这样简单的事情。</p><p>你生活中反复出现的这些问题,都是有解决方案的。</p><p>你的任务就是识别出那些问题,自我教育,然后不断尝试各种解决方案,直到找到真正有效的那一个。这个过程本身也会提升你改变的可能性。</p><h3 id="_3-在当前世界观内感受到的不协调" tabindex="-1">3) 在当前世界观内感受到的不协调 <a class="header-anchor" href="#_3-在当前世界观内感受到的不协调" aria-label="Permalink to &quot;3) 在当前世界观内感受到的不协调&quot;">​</a></h3><p>这是我最喜欢的一点,因为你在我们这个圈子里经常能看到它。</p><p>一个典型的例子就是像Chris Williamson这样的人,他在跟我们一起录播客时提到,自己曾觉得必须时刻保持忙碌才能感到心安。他一直把休息看作是一种软弱,直到最近才有所改变,而且他至今仍在以某种方式与这个问题较劲。</p><p>对于许多正从“蓝色”阶段迈向“橙色”阶段的孩子来说,他们会觉得自己成长过程中被灌输的信念——比如去教堂、崇拜某个特定的神——已经不再与自己产生共鸣。这些信念无法充分回答他们的疑问,从而产生一种不满足感,激发出他们想要探求更多知识的好奇心。</p><h3 id="_4-洞察点与对其他路径的觉察" tabindex="-1">4) 洞察点与对其他路径的觉察 <a class="header-anchor" href="#_4-洞察点与对其他路径的觉察" aria-label="Permalink to &quot;4) 洞察点与对其他路径的觉察&quot;">​</a></h3><p>在与这种不协调共处一段时间,并对其他方式保持开放之后,他们会到达一个洞察点,在那一刻,一切仿佛同时涌入他们的心灵。</p><p>那些痴迷于生产力的人会意识到,休息其实能提升他们产出的质量。他们的工作方式可能会改变,但即使整体产量下降,他们的作品质量却会显著提升。</p><p>那个好奇的孩子会找到一个新的信念体系,全身心投入并以此认同自己——无论好坏,这也可能构成一个陷阱,如果他们因此关闭心智、不再向下一阶段敞开的话。</p><h3 id="_5-消除、绕过、化解或重新定义障碍" tabindex="-1">5) 消除、绕过、化解或重新定义障碍 <a class="header-anchor" href="#_5-消除、绕过、化解或重新定义障碍" aria-label="Permalink to &quot;5) 消除、绕过、化解或重新定义障碍&quot;">​</a></h3><p>一旦你被拉扯在两个相对的极端之间(你旧有的生活方式和你想要采取的新方式),你就会在这条路上遇到障碍。</p><p>如果你是一个有志成为作家的人,你可能会陷入完美主义的陷阱。</p><p>你开始一个项目,然后又放弃,因为它永远达不到你满意的程度。</p><p>面对这个特定的障碍,你需要重新定义自己与完美主义之间的关系。你需要意识到,唯一能变好的方法,就是先从一个让你感到尴尬的东西开始——同时明白别人其实并没有那么在意——然后在持续练习这门手艺的过程中不断进步。</p><h3 id="_6-预料到会有困惑期和漫长的学习曲线" tabindex="-1">6) 预料到会有困惑期和漫长的学习曲线 <a class="header-anchor" href="#_6-预料到会有困惑期和漫长的学习曲线" aria-label="Permalink to &quot;6) 预料到会有困惑期和漫长的学习曲线&quot;">​</a></h3><p>所有这一切都是悬而未定的,因为没有人能告诉你该做什么,他们只能告诉你他们自己是怎么做的,而这就忽略了以下几点:</p><ul><li>你的价值体系</li><li>你目前所处的发展阶段</li><li>你的个性、信念、身份认同、目标,以及其他种种</li></ul><p>在这个阶段,教育的目的是觉察。</p><p>我可以给你举例子、给你方法流程,但如果你没有能力理解自己身处何处、自己是谁,那些东西对你的帮助就很有限。</p><p>这条路会令人困惑。</p><p>它本就不该在此刻就说得通。</p><p>当你在做一件全新的事情时,你本来就应该处于迷失的状态,而不是别的样子——因为你正在大海中央挣扎扑腾,直到你学会游泳(或者造出一条船)。</p><p>我希望通过这篇文章,我给你带来的不是那些具体该做的实际步骤,而是一些参照点,让你可以从此开始犯下更好的错误。</p><p>感谢阅读。</p><p>—— Dan</p><hr><p><a href="/en/letters/how-to-unfck-your-life-evidence-based">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',198))])}const C=n(u,[["render",g]]);export{w as __pageData,C as default};
